import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.C8822HRV.js";const g=JSON.parse('{"title":"sdd CLI reference","description":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial.","frontmatter":{"title":"sdd CLI reference","description":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial.","head":[["meta",{"property":"og:title","content":"sdd CLI reference · sdd"}],["meta",{"property":"og:description","content":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/reference/cli/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"sdd CLI reference · sdd"}],["meta",{"name":"twitter:description","content":"Friendly sdd command list — what each command does and when to use it. For learning by doing, start with the 10-minute tutorial."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/reference/cli/"}]]},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1785895617000}'),a={name:"reference/cli.md"};function c(n,t,s,i,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>Binary name: <strong><code>sdd</code></strong>.<br> Install: <strong><a href="https://www.npmjs.com/package/@structured-vibe-coding/cli" target="_blank" rel="noreferrer">@structured-vibe-coding/cli on npm</a></strong><br> Learn by doing: <a href="./../tutorials/first-change">Start in 10 minutes</a>.<br> One command’s flags: <code>sdd &lt;command&gt; --help</code>.</p><hr><h2 id="start-work-which-command" tabindex="-1">Start work: which command? <a class="header-anchor" href="#start-work-which-command" aria-label="Permalink to &quot;Start work: which command?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Command</th></tr></thead><tbody><tr><td>Everyday / ad-hoc title (bug, small feature, spike)</td><td><strong><code>sdd new &quot;Title&quot;</code></strong> (optional <code>-w hotfix|feature|…</code>)</td></tr><tr><td>Item from product backlog after greenfield (<code>F-001</code>)</td><td><strong><code>sdd backlog start F-001</code></strong></td></tr><tr><td>New product discovery (vision → backlog)</td><td><strong><code>sdd greenfield &quot;One-line idea&quot;</code></strong></td></tr></tbody></table><p><code>sdd new</code> and <code>sdd backlog start</code> both open a <strong>change pack</strong>. The difference is the <strong>source</strong>: free-form title vs backlog id.<br><code>-w feature</code> is a <strong>workflow pack name</strong>, not the same as <code>sdd backlog</code> / the old <code>sdd feature</code> alias.</p><hr><h2 id="i-want-to" tabindex="-1">I want to… <a class="header-anchor" href="#i-want-to" aria-label="Permalink to &quot;I want to…&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Set up this project</td><td><code>sdd init --here --ai copilot</code></td></tr><tr><td>Check setup</td><td><code>sdd doctor</code></td></tr><tr><td>Start small work</td><td><code>sdd new &quot;Title&quot; -w hotfix -y</code></td></tr><tr><td>Start mid-size work (workflow pack)</td><td><code>sdd new &quot;Title&quot; -w feature -y</code></td></tr><tr><td>Start a new product</td><td><code>sdd greenfield &quot;One-line idea&quot;</code></td></tr><tr><td>See product backlog</td><td><code>sdd backlog list</code></td></tr><tr><td>Build backlog item</td><td><code>sdd backlog start F-001</code></td></tr><tr><td>See where I am</td><td><code>sdd status</code></td></tr><tr><td>Move to next step</td><td><code>sdd next</code></td></tr><tr><td>Finish work</td><td><code>sdd complete</code></td></tr><tr><td>Check the change works</td><td><code>sdd verify</code></td></tr><tr><td>Improve current notes</td><td><code>sdd refine</code></td></tr><tr><td>Get help from AI now</td><td><code>sdd agent</code></td></tr><tr><td>Don’t open AI this time</td><td>add <code>--no-agent</code></td></tr></tbody></table><hr><h2 id="all-commands" tabindex="-1">All commands <a class="header-anchor" href="#all-commands" aria-label="Permalink to &quot;All commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>When</th></tr></thead><tbody><tr><td><code>sdd init</code></td><td>Create sdd files + one AI setup</td><td>Once per app</td></tr><tr><td><code>sdd init --force</code></td><td>Refresh defaults (keeps your memory files)</td><td>Upgrades</td></tr><tr><td><code>sdd new &quot;title&quot;</code></td><td>Start a change pack from a free-form title</td><td>Everyday work</td></tr><tr><td><code>sdd new … -w &lt;pack&gt;</code></td><td>Choose path (hotfix, feature, …)</td><td>You know the path</td></tr><tr><td><code>sdd new … -y</code></td><td>Skip confirm prompts</td><td>Scripts / CI</td></tr><tr><td><code>sdd greenfield &quot;idea&quot;</code></td><td>New product plan path</td><td>Empty / MVP product</td></tr><tr><td><code>sdd backlog list</code></td><td>Show F-001… product backlog</td><td>After greenfield</td></tr><tr><td><code>sdd backlog start F-001</code></td><td>Start work from backlog id</td><td>Build product items</td></tr><tr><td><code>sdd feature list|start</code></td><td><strong>Alias</strong> for <code>sdd backlog …</code> (compat)</td><td>Old scripts</td></tr><tr><td><code>sdd status</code></td><td>Progress (<strong>no</strong> AI)</td><td>Anytime</td></tr><tr><td><code>sdd status --list</code></td><td>All open changes</td><td>Several PRs</td></tr><tr><td><code>sdd next</code></td><td>Advance one stage</td><td>Step done</td></tr><tr><td><code>sdd next --force</code></td><td>Bypass checks</td><td>Emergency only</td></tr><tr><td><code>sdd skip &lt;stage&gt; -r &quot;…&quot;</code></td><td>Skip a stage</td><td>Not needed</td></tr><tr><td><code>sdd use &lt;workflow&gt;</code></td><td>Switch path mid-flight</td><td>Scope changed</td></tr><tr><td><code>sdd gate approve|waive|fail</code></td><td>Approve / waive / fail a gate</td><td>Enterprise gates</td></tr><tr><td><code>sdd verify</code></td><td>Local check step</td><td>Before complete</td></tr><tr><td><code>sdd verify --no-run</code></td><td>Checklist only</td><td>Manual testing</td></tr><tr><td><code>sdd complete</code></td><td>Mark done (greenfield also saves to <code>memory/</code>)</td><td>Finished</td></tr><tr><td><code>sdd refine [stage]</code></td><td>Improve notes</td><td>Spec quality</td></tr><tr><td><code>sdd refine --analyze</code></td><td>Report only</td><td>Audit</td></tr><tr><td><code>sdd context</code></td><td>Focused AST code slices</td><td>Implement</td></tr><tr><td><code>sdd mcp sources list/add/test/remove</code></td><td>External MCPs <strong>sdd calls</strong></td><td>Design system / AST / org lib</td></tr><tr><td><code>sdd mcp fetch</code></td><td>Pull matching sources for current stage</td><td>Enrich handoff / implement</td></tr><tr><td><code>sdd agent</code></td><td>Refresh brief + open AI</td><td>Anytime</td></tr><tr><td><code>sdd checkout &lt;id&gt;</code></td><td>Switch active change</td><td>Multi-PR</td></tr><tr><td><code>sdd workflows</code></td><td>List paths</td><td>Discover</td></tr><tr><td><code>sdd help</code></td><td>Short overview</td><td>First run</td></tr><tr><td><code>sdd doctor</code></td><td>Health check</td><td>Stuck / setup</td></tr></tbody></table><h3 id="greenfield-backlog" tabindex="-1">Greenfield / backlog <a class="header-anchor" href="#greenfield-backlog" aria-label="Permalink to &quot;Greenfield / backlog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>sdd greenfield [&quot;idea&quot;]</code></td><td>Asks for idea if you omit it; supports <code>--no-agent</code></td></tr><tr><td><code>sdd backlog start F-001</code></td><td><code>-w</code> can override the backlog workflow; supports <code>--no-agent</code></td></tr><tr><td><code>sdd backlog list</code></td><td>Never opens the AI</td></tr><tr><td><code>sdd feature …</code></td><td>Same as <code>sdd backlog …</code>; prefer <strong>backlog</strong> in new docs and scripts</td></tr></tbody></table><hr><h2 id="about-the-ai-opening" tabindex="-1">About the AI opening <a class="header-anchor" href="#about-the-ai-opening" aria-label="Permalink to &quot;About the AI opening&quot;">​</a></h2><p>Most process commands refresh a short handoff and may open your AI.<br><strong>Never open AI:</strong> <code>status</code>, <code>init</code>, <code>workflows</code>, <code>context</code>, <code>backlog list</code>, <code>help</code>, <code>doctor</code>.</p><p>Turn AI off for one command: <code>--no-agent</code> or <code>SDD_NO_AGENT=1</code>.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guides/everyday-loop">Everyday loop</a></li><li><a href="./../guides/greenfield">Greenfield</a></li><li><a href="./../guides/agents">AI setup</a></li><li><a href="./../guides/mcp">MCP sources</a></li><li><a href="./../guides/code-context">Code context</a></li></ul>',21)])])}const m=d(a,[["render",c]]);export{g as __pageData,m as default};
